import{_ as e,o as a,c as n,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"Entrar com GitHub ou Google","description":"","frontmatter":{},"headers":[],"relativePath":"pt-BR/guide/sign-in.md","filePath":"pt-BR/guide/sign-in.md"}'),i={name:"pt-BR/guide/sign-in.md"};function t(s,o,d,u,c,l){return a(),n("div",null,[...o[0]||(o[0]=[r('<h1 id="entrar-com-github-ou-google" tabindex="-1">Entrar com GitHub ou Google <a class="header-anchor" href="#entrar-com-github-ou-google" aria-label="Permalink to &quot;Entrar com GitHub ou Google&quot;">​</a></h1><p>As pessoas podem entrar no Orbit com GitHub ou Google em vez de uma senha. O Orbit encontra a conta cujo e-mail o provedor verificou, então ele nunca cria uma conta sozinho: quem não tem conta precisa antes de um <a href="./members#inviting">convite</a>.</p><h2 id="setup" tabindex="-1">Configurando <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Configurando {#setup}&quot;">​</a></h2><p>Cada provedor precisa de um app OAuth seu. O administrador do Orbit configura em <strong>Configurações → Entrar com GitHub e Google</strong>, onde <strong>Configurar</strong> mostra a URL de retorno para registrar, como <code>https://orbit.exemplo.com/sign-in/github/callback</code>.</p><ul><li><strong>GitHub:</strong> em GitHub → Settings → Developer settings → OAuth Apps, crie um novo OAuth app. Use o endereço do console como homepage URL e a URL de retorno que o Orbit mostra como authorization callback URL. Copie o client ID, gere um client secret e salve os dois no Orbit.</li><li><strong>Google:</strong> no Google Cloud, em APIs e serviços → Credenciais, crie um ID de cliente OAuth do tipo <strong>Aplicativo da Web</strong> e adicione a URL de retorno que o Orbit mostra aos URIs de redirecionamento autorizados. Salve o client ID e o secret no Orbit. O Orbit pede os escopos <code>openid</code>, <code>email</code> e <code>profile</code>.</li></ul><p>O client secret é guardado criptografado e nunca mais aparece; salvar sem ele mantém o que já estava salvo. A URL de retorno acompanha <a href="./install#console-address">o endereço do console</a>: quando ele muda, registre a nova no provedor.</p><h2 id="signing-in" tabindex="-1">Entrando <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Entrando {#signing-in}&quot;">​</a></h2><p><strong>Continuar com GitHub</strong> e <strong>Continuar com Google</strong> aparecem na página de login quando um provedor está configurado.</p><ul><li>O Orbit pede ao provedor os e-mails que ele verificou, o principal do GitHub primeiro, e entra na conta que usa um deles. Um e-mail que o provedor não verificou nunca é usado.</li><li>Com o <a href="./two-factor">login em dois fatores</a> ligado, o Orbit pede o código depois do provedor, como faz depois da senha.</li><li>Quando nenhuma conta usa esses e-mails, o login para e diz qual e-mail recebeu.</li><li>Um login precisa terminar em 10 minutos, e o link dele funciona uma vez.</li></ul><h2 id="invitations" tabindex="-1">Convites <a class="header-anchor" href="#invitations" aria-label="Permalink to &quot;Convites {#invitations}&quot;">​</a></h2><p>Um convite pode ser aceito com <strong>Continuar com GitHub</strong> ou <strong>Continuar com Google</strong> quando o provedor verificou o e-mail convidado. Um membro novo entra sem senha e daí em diante entra pelo provedor; quem já tem conta entra com ela.</p><h2 id="turning-off" tabindex="-1">Desligando <a class="header-anchor" href="#turning-off" aria-label="Permalink to &quot;Desligando {#turning-off}&quot;">​</a></h2><p><strong>Remover</strong> para o login com aquele provedor. As sessões abertas continuam e as senhas continuam funcionando. Membros que entraram pelo provedor não têm senha, então só conseguem entrar quando o provedor for configurado de novo.</p>',13)])])}const p=e(i,[["render",t]]);export{g as __pageData,p as default};
